            { q: "The storm in the story symbolizes:", p: "The character faced a terrible storm and emerged stronger.", a: ["Weather", "Internal struggle", "Just rain"], c: 1, passage_title: "The Storm Within", a_explanations: ["Incorrect. The weather is the literal element, not the symbolism.", "Correct! A storm often symbolizes internal conflict or emotional turmoil.", "Incorrect. The storm represents more than just precipitation."], hint: "What does an internal 'storm' often represent in literature?" },
            { q: "What does the journey represent?", p: "Her journey across the desert was her spiritual awakening.", a: ["Physical travel", "Personal growth", "A vacation"], c: 1, passage_title: "The Spiritual Journey", a_explanations: ["Incorrect. The physical travel is not what the journey symbolizes.", "Correct! The passage explicitly says the journey was a spiritual awakening.", "Incorrect. A vacation is leisure, not a spiritual journey."], hint: "What does the passage say the journey actually was?" },
            { q: "The locked door means:", p: "He couldn't open the locked door to his past.", a: ["A closed door", "Unreachable past", "Just locked"], c: 1, passage_title: "The Locked Door", a_explanations: ["Incorrect. The door being closed is the literal state.", "Correct! A locked door to the past symbolizes memories or experiences that cannot be accessed.", "Incorrect. The lock represents more than a physical mechanism."], hint: "What does a door to the past that cannot be opened represent?" },
            { q: "The butterfly symbolizes:", p: "From a caterpillar, she transformed into a butterfly.", a: ["Insects", "Transformation", "Butterflies"], c: 1, passage_title: "Metamorphosis", a_explanations: ["Incorrect. The butterfly is not just an insect in this context.", "Correct! A butterfly is a classic symbol of transformation and change.", "Incorrect. The butterfly represents more than its literal self."], hint: "What is the most common symbolic meaning of a butterfly?" },
            { q: "What does the river represent?", p: "The river flowed endlessly, like the passage of time.", a: ["Water flow", "Time's passage", "Just water"], c: 1, passage_title: "The Endless River", a_explanations: ["Incorrect. The physical flow is not the symbolism.", "Correct! The passage directly compares the river to the passage of time.", "Incorrect. The river represents a concept, not just water."], hint: "What does the passage compare the river to?" },
            { q: "The rose stands for:", p: "Among thorns, the rose bloomed, representing beauty amid pain.", a: ["A flower", "Beauty in adversity", "Just a plant"], c: 1, passage_title: "The Rose and Thorns", a_explanations: ["Incorrect. The rose is more than just a flower here.", "Correct! The rose blooming among thorns symbolizes beauty emerging from hardship.", "Incorrect. The rose represents an idea, not just a plant."], hint: "What does beauty among thorns suggest about difficult circumstances?" },
            { q: "The empty room means:", p: "The empty room symbolized his sense of loss.", a: ["No furniture", "Feeling of loss", "Just empty"], c: 1, passage_title: "The Empty Room", a_explanations: ["Incorrect. The lack of furniture is the literal state.", "Correct! The empty room represents the character's emotional emptiness after loss.", "Incorrect. The room symbolizes an emotion, not just emptiness."], hint: "What emotion does an empty room often represent after someone leaves?" },
            { q: "What does the lighthouse symbolize?", p: "The lighthouse stood on the cliff through every storm, its beam cutting through the darkness. For generations, sailors had relied on its steady light to find safe harbor. When the old keeper grew too ill to maintain it, the whole village took turns climbing the stairs each evening to make sure the lamp was lit.", a: ["A building on a cliff", "Guidance, hope, and community responsibility", "A tourist attraction", "An old-fashioned light"], c: 1, explanation: "The lighthouse guides sailors through darkness, symbolizing guidance and hope, while the villagers maintaining it shows community responsibility.", passage_title: "The Village Lighthouse", a_explanations: ["Incorrect. The physical location is not the symbolism.", "Correct! The lighthouse represents guidance, hope, and the community's shared responsibility.", "Incorrect. The lighthouse is functional, not for tourism.", "Incorrect. While old-fashioned, the light represents deeper values."], hint: "What do the lighthouse and the villagers' actions together represent?" },
            { q: "What does the garden represent?", p: "At the beginning of the novel, the garden is overgrown with weeds and thorns. By the end, the same garden blooms with colorful flowers and fresh vegetables. The transformation mirrors the protagonist's own journey from grief to renewal.", a: ["Just a backyard", "Personal growth and healing", "Spring weather", "Hard work pays off"], c: 1, explanation: "The garden's transformation from weeds to blooms parallels the character's journey from grief to healing.", passage_title: "The Transformed Garden", a_explanations: ["Incorrect. The garden is not just a physical space.", "Correct! The garden's transformation mirrors the character's healing from grief.", "Incorrect. The garden represents internal change, not just seasons.", "Incorrect. While work is involved, the garden symbolizes emotional growth."], hint: "What does the garden's change parallel in the protagonist's life?" }
