            { q: "What is the author's goal?", p: "She told a humorous story about her pet's antics.", a: ["Inform", "Entertain", "Persuade"], c: 1, passage_title: "The Pet Story", a_explanations: ["Incorrect. A humorous story is not primarily informative.", "Correct! The author wants to entertain with a funny story.", "Incorrect. The author is not trying to change opinions."], hint: "Why would someone tell a funny story about their pet?" },
            { q: "The author intended to:", p: "He explained the scientific process of photosynthesis.", a: ["Teach", "Amuse", "Criticize"], c: 0, passage_title: "Photosynthesis Explained", a_explanations: ["Correct! The author is teaching a scientific process.", "Incorrect. A scientific explanation is not meant to amuse.", "Incorrect. The author is explaining, not criticizing."], hint: "What is the author doing with the scientific process?" },
            { q: "The purpose of this text:", p: "A letter urges readers to support a local cause.", a: ["Inform only", "Persuade to action", "Tell a story"], c: 1, passage_title: "The Support Letter", a_explanations: ["Incorrect. Urging action goes beyond just informing.", "Correct! The letter aims to persuade readers to take action.", "Incorrect. A letter urging action is not telling a story."], hint: "What is the author trying to get readers to do?" },
            { q: "Why was this written?", p: "An article describes how to bake a perfect cake.", a: ["Teach a skill", "Share opinion", "Tell a story"], c: 0, passage_title: "Baking Instructions", a_explanations: ["Correct! The article teaches readers how to bake a cake.", "Incorrect. Instructions are not opinions.", "Incorrect. A how-to article is not a narrative story."], hint: "What type of text gives step-by-step instructions?" },
            { q: "The author's intent:", p: "She wrote a poem expressing her emotions about loss.", a: ["Educate", "Express emotions", "Debate"], c: 1, passage_title: "Poem of Loss", a_explanations: ["Incorrect. Poetry is not primarily for education.", "Correct! The poem is a vehicle for expressing emotions.", "Incorrect. A poem is not a structured debate."], hint: "Why do people write poems about personal experiences?" },
            { q: "What's the main purpose?", p: "An ad explains why you need this product.", a: ["Inform", "Persuade", "Entertain"], c: 1, passage_title: "Product Advertisement", a_explanations: ["Incorrect. Ads do more than inform - they try to sell.", "Correct! The ad's purpose is to persuade you to buy the product.", "Incorrect. Ads are not primarily for entertainment."], hint: "What is the goal of an advertisement?" },
            { q: "The author wanted to:", p: "He described his adventures traveling across Europe.", a: ["Inform", "Share experiences", "Persuade"], c: 1, passage_title: "European Travels", a_explanations: ["Incorrect. Personal stories go beyond just informing.", "Correct! The author is sharing his travel experiences with readers.", "Incorrect. The author is not trying to change beliefs."], hint: "What do authors do when they write about their personal adventures?" },
            { q: "The writing purpose:", p: "A review criticizes the movie's poor plot.", a: ["Share opinion", "Inform", "Entertain"], c: 0, passage_title: "Movie Review", a_explanations: ["Correct! A review expresses the author's critical opinion.", "Incorrect. A review is not just factual information.", "Incorrect. While reviews can be entertaining, their primary purpose is evaluation."], hint: "What does a critic do when writing a review?" },
            { q: "What is the author's primary purpose?", p: "The article begins by describing the problem of plastic pollution in oceans. It then explains how plastic harms marine animals and damages ecosystems. Finally, it suggests three actions readers can take to reduce plastic waste. The tone is urgent but hopeful.", a: ["To entertain with a story", "To inform and persuade readers to act", "To describe a scientific experiment", "To criticize specific companies"], c: 1, explanation: "The author both informs about the problem and persuades readers to take action.", passage_title: "Plastic Pollution Article", a_explanations: ["Incorrect. The article is informational, not fictional entertainment.", "Correct! The author informs about the problem and persuades readers to take action.", "Incorrect. The article discusses pollution broadly, not a single experiment.", "Incorrect. The author focuses on solutions, not blaming companies."], hint: "What two purposes does the author combine in this article?" }
